def transform(grid):
    """Stamp the five-cell legend row over each isolated marker, centered on it."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = max(set(v for row in g for v in row), key=lambda v: sum(x == v for row in g for x in row))

    # The legend is the row containing a horizontal contiguous run of five
    # non-background cells; the sparse marker field contains only singletons.
    legend_row = None
    pattern = None
    for r, row in enumerate(g):
        for c in range(w - 4):
            run = row[c:c + 5]
            if all(v != bg for v in run):
                legend_row, pattern = r, run[:]
                break
        if legend_row is not None:
            break
    if pattern is None:
        raise ValueError('five-cell legend not found')

    markers = []
    for r, row in enumerate(g):
        if r == legend_row:
            continue
        for c, value in enumerate(row):
            if value != bg:
                markers.append((r, c))
    for r, c in markers:
        start = c - 2
        if start < 0 or start + 5 > w:
            raise ValueError('marker too close to edge')
        g[r][start:start + 5] = pattern
    return g

